SELECT "stadium"."Name" FROM "stadium"
LEFT JOIN "concert" ON "stadium"."Stadium_ID" = "concert"."Stadium_ID"
GROUP BY "stadium"."Stadium_ID", "stadium"."Name";

SELECT DISTINCT "model_list"."Model" FROM "model_list" JOIN "car_makers" ON "model_list"."Maker" = "car_makers"."Maker" WHERE "car_makers"."FullName" = 'General Motors'
UNION
SELECT DISTINCT "model_list"."Model" FROM "model_list" JOIN "car_names" ON "model_list"."Model" = "car_names"."Model" JOIN "cars_data" ON "car_names"."MakeId" = "cars_data"."Id" WHERE "cars_data"."Weight" > 3500;

SELECT DISTINCT "Year" FROM "cars_data" WHERE "Weight" < 4000
INTERSECT
SELECT DISTINCT "Year" FROM "cars_data" WHERE "Weight" > 3000;
